mapper.select:
SELECT kd.id, kd.user_name, kd.commission, kd.create_time, kd.service_code, kd.service_name, kd.service_type, kd.item_type, kd.performance, kd.quantity, so.org_name FROM kpi_detail kd LEFT JOIN sys_org so ON so.id = kd.org_id
AND kd.user_name LIKE CONCAT('%', #{query.username}, '%')
AND kd.org_id = #{query.orgId}
AND kd.create_time >= #{query.beginDate}
AND kd.create_time <= #{query.endDate}
ORDER BY kd.create_time DESC
